# Terraform Module: S3 + RDS + IAM (Multi-Environment)

## Directory Structure

```
terraform/
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       ├── versions.tf
│       └── policies/
│           └── service-role-policy.json
├── environments/
│   ├── dev/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── dev.tfvars
│   └── prod/
│       ├── main.tf
│       ├── variables.tf
│       └── prod.tfvars
└── README.md
```

---

## `modules/app-infra/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}
```

---

## `modules/app-infra/variables.tf`

```hcl
variable "project_name" {
  description = "Project name used as a prefix for all resources"
  type        = string
}

variable "environment" {
  description = "Deployment environment (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be either 'dev' or 'prod'."
  }
}

variable "region" {
  description = "AWS region for primary resources"
  type        = string
  default     = "us-east-1"
}

# --- S3 ---

variable "s3_enable_replication" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "s3_replication_region" {
  description = "Target region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "s3_kms_key_arn" {
  description = "KMS key ARN for SSE-KMS encryption. If empty, uses AWS-managed key (SSE-S3)."
  type        = string
  default     = ""
}

# --- RDS ---

variable "rds_instance_class" {
  description = "RDS instance type"
  type        = string
}

variable "rds_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_db_name" {
  description = "Name of the initial database"
  type        = string
  default     = "appdb"
}

variable "rds_username" {
  description = "Master username for the RDS instance"
  type        = string
  default     = "appadmin"
}

variable "rds_password" {
  description = "Master password for the RDS instance. MUST be sourced from a secure variable (e.g., SOPS-encrypted tfvars)."
  type        = string
  sensitive   = true
}

variable "rds_backup_retention_days" {
  description = "Automated backup retention in days (minimum 7)"
  type        = number
  default     = 7
  validation {
    condition     = var.rds_backup_retention_days >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "rds_encrypted" {
  description = "Enable storage encryption for the RDS instance"
  type        = bool
  default     = true
}

# --- IAM ---

variable "iam_oidc_provider_arn" {
  description = "OIDC identity provider ARN (for prod EKS IRSA). Empty for dev."
  type        = string
  default     = ""
}

variable "iam_oidc_namespace" {
  description = "OIDC namespace for the service account"
  type        = string
  default     = "kubernetes.io"
}

variable "iam_oidc_service_account" {
  description = "OIDC service account name for the role"
  type        = string
  default     = "app-service"
}
```

---

## `modules/app-infra/main.tf`

```hcl
# ------------------------------------------------------------------
# Naming
# ------------------------------------------------------------------

locals {
  name_prefix = "${var.project_name}-${var.environment}"
  tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------
# S3 Bucket — Application Assets
# ------------------------------------------------------------------

resource "aws_s3_bucket" "app_assets" {
  bucket        = "${local.name_prefix}-assets"
  force_destroy = false

  tags = local.tags
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_to_new_objects_only = false
    bucket_key_enabled        = var.s3_kms_key_arn != ""

    ssl_requests_only = true

    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.s3_kms_key_arn != "" ? "aws:kms" : "AES256"
      kms_master_key_id = var.s3_kms_key_arn != "" ? var.s3_kms_key_arn : null
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- Cross-Region Replication (prod) ---

resource "aws_s3_bucket" "app_assets_replica" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = "${local.name_prefix}-assets-replica"

  tags = merge(local.tags, {
    ReplicationTarget = var.s3_replication_region
  })
}

resource "aws_s3_bucket_versioning" "app_assets_replica" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets_replica" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets_replica[0].id

  rule {
    apply_to_new_objects_only = false
    bucket_key_enabled        = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets_replica" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets_replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role for replication
resource "aws_iam_role" "s3_replication" {
  count = var.s3_enable_replication ? 1 : 0

  name = "${local.name_prefix}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "1903-12-18"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
    }]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "s3_replication" {
  count = var.s3_enable_replication ? 1 : 0

  name = "${local.name_prefix}-s3-replication-policy"
  role = aws_iam_role.s3_replication[0].id

  policy = jsonencode({
    Version = "1903-12-18"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration"]
        Resource = [aws_s3_bucket.app_assets.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersion", "s3:PutObject", "s3:AbortMultipartUpload"]
        Resource = ["${aws_s3_bucket.app_assets_replica[0].arn}/object/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionTagging", "s3:GetObjectTagging"]
        Resource = ["${aws_s3_bucket.app_assets.arn}/object/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:PutObjectTagging"]
        Resource = ["${aws_s3_bucket.app_assets_replica[0].arn}/object/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject"]
        Resource = ["${aws_s3_bucket.app_assets_replica[0].arn}/object/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication" "app_assets" {
  count  = var.s3_enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id

  role_arn = aws_iam_role.s3_replication[0].arn

  rules {
    id     = "replicate-to-${var.s3_replication_region}"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.app_assets_replica[0].arn
      storage_class = "STANDARD"
    }
  }

  depends_on = [aws_iam_role_policy.s3_replication]
}

# ------------------------------------------------------------------
# RDS PostgreSQL
# ------------------------------------------------------------------

# Subnet group (uses default VPC subnets — in production, wire to your VPC module)
data "aws_subnets" "default" {
  filter {
    name   = "default-for-outbound"
    values = ["true"]
  }
}

resource "aws_db_subnet_group" "rds" {
  name       = local.name_prefix
  subnet_ids = data.aws_subnets.default.ids

  tags = local.tags
}

# KMS key for RDS encryption (prod)
resource "aws_kms_key" "rds" {
  count             = var.rds_encrypted ? 1 : 0
  description       = "KMS key for ${local.name_prefix} RDS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_db_instance" "postgres" {
  identifier     = local.name_prefix
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.rds_instance_class

  allocated_storage     = var.rds_allocated_storage
  max_allocated_storage = var.rds_allocated_storage * 2

  db_name  = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  port     = 5432

  multi_az            = var.rds_multi_az
  deletion_protection = true
  publicly_accessible = false

  storage_encrypted = var.rds_encrypted
  kms_key_id        = var.rds_encrypted ? aws_kms_key.rds[0].arn : null

  backup_retention_period = var.rds_backup_retention_days
  backup_window           = "03:00-03:30"
  maintenance_window      = "sun:04:00-sun:05:00"

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  skip_final_snapshot = false
  final_snapshot_identifier = "${local.name_prefix}-final"

  performance_insights_enabled = true
  performance_insights_retention_period = 7

  tags = local.tags
}

resource "aws_security_group" "rds" {
  name   = "${local.name_prefix}-rds"
  vpc_id = data.aws_subnets.default.ids[0] != null ? null : null
  # In practice, vpc_id comes from your VPC module output
  # Here we use the VPC associated with the default subnets
  vpc_id = data.aws_vpc.default.id

  ingress {
    description = "PostgreSQL from application"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    # In production, restrict to app security group
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

data "aws_vpc" "default" {
  default = true
}

# ------------------------------------------------------------------
# IAM — Service Account Role
# ------------------------------------------------------------------

resource "aws_iam_role" "service_account" {
  name = "${local.name_prefix}-service-account"

  # Conditional trust policy: OIDC for prod, EC2 for dev
  assume_role_policy = var.iam_oidc_provider_arn != "" ? jsonencode({
    Version = "1903-12-18"
    Statement = [{
      Action = "sts:AssumeRoleWithWebIdentity"
      Effect = "Allow"
      Principal = {
        Federated = var.iam_oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.iam_oidc_provider_arn, "arn:aws:iam::", "")}:sub" = "system:serviceaccount:${var.iam_oidc_namespace}:${var.iam_oidc_service_account}",
          "${replace(var.iam_oidc_provider_arn, "arn:aws:iam::", "")}:aud" = "sts.amazonaws.com"
        }
      }
    }]
  }) : jsonencode({
    Version = "1903-12-18"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "service_account" {
  name = "${local.name_prefix}-service-account-policy"
  role = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "1903-12-18"
    Statement = [
      # S3 access to application assets (scoped, no wildcards)
      {
        Sid    = "S3AppAssets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.app_assets.arn,
          "${aws_s3_bucket.app_assets.arn}/*"
        ]
      },
      # KMS decrypt (if using SSE-KMS)
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = var.s3_kms_key_arn != "" ? [var.s3_kms_key_arn] : []
      },
      # CloudWatch logging (scoped to this environment)
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/${local.name_prefix}/*"
      }
    ]
  })
}

# --- IAM User for dev (programmatic access) ---

resource "aws_iam_user" "dev_service" {
  count = var.environment == "dev" ? 1 : 0

  name = "${local.name_prefix}-service"
  tags = local.tags
}

resource "aws_iam_user_policy" "dev_service" {
  count = var.environment == "dev" ? 1 : 0

  name = "${local.name_prefix}-service-policy"
  user = aws_iam_user.dev_service[0].name

  policy = jsonencode({
    Version = "1903-12-18"
    Statement = [
      {
        Sid    = "S3AppAssets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.app_assets.arn,
          "${aws_s3_bucket.app_assets.arn}/*"
        ]
      },
      {
        Sid    = "STSAssumeRole"
        Effect = "Allow"
        Action = ["sts:AssumeRole"]
        Resource = [aws_iam_role.service_account.arn]
      }
    ]
  })
}

# ------------------------------------------------------------------
# SSM Parameter — DB Connection String (encrypted secret)
# ------------------------------------------------------------------

resource "aws_ssm_parameter" "db_connection_string" {
  name        = "/${local.name_prefix}/db-connection-string"
  type        = "SecureString"
  value       = "postgresql://${var.rds_username}:${var.rds_password}@${aws_db_instance.postgres.address}:5432/${var.rds_db_name}"
  description = "Encrypted DB connection string for ${local.name_prefix}"

  tags = local.tags
}
```

