## `modules/app-infra/outputs.tf`

```hcl
output "s3_bucket_name" {
  description = "Name of the S3 assets bucket"
  value       = aws_s3_bucket.app_assets.id
}

output "s3_bucket_arn" {
  description = "ARN of the S3 assets bucket"
  value       = aws_s3_bucket.app_assets.arn
}

output "s3_replica_bucket_arn" {
  description = "ARN of the S3 replica bucket (null if replication disabled)"
  value       = var.s3_enable_replication ? aws_s3_bucket.app_assets_replica[0].arn : null
}

output "rds_endpoint" {
  description = "RDS endpoint (host:port)"
  value       = aws_db_instance.postgres.endpoint
}

output "rds_address" {
  description = "RDS hostname"
  value       = aws_db_instance.postgres.address
}

output "rds_port" {
  description = "RDS port"
  value       = aws_db_instance.postgres.port
}

output "rds_resource_id" {
  description = "RDS resource ID (for KMS key ARN construction)"
  value       = aws_db_instance.postgres.resource_id
}

output "iam_role_arn" {
  description = "ARN of the service account IAM role"
  value       = aws_iam_role.service_account.arn
}

output "iam_user_name" {
  description = "Name of the dev IAM user (null in prod)"
  value       = var.environment == "dev" ? aws_iam_user.dev_service[0].name : null
}

output "db_connection_string_parameter" {
  description = "SSM parameter name for the DB connection string (SecureString)"
  value       = aws_ssm_parameter.db_connection_string.name
}

output "db_connection_string" {
  description = "DB connection string (sensitive — do not log)"
  value       = aws_ssm_parameter.db_connection_string.value
  sensitive   = true
}
```

