## `environments/dev/dev.tfvars`

```hcl
# Environment overrides for dev
environment = "dev"
region      = "us-east-1"

# RDS — dev sizing
rds_instance_class        = "db.t3.micro"
rds_multi_az              = false
rds_allocated_storage     = 20
rds_backup_retention_days = 7
rds_encrypted             = true

# S3 — no replication in dev
s3_enable_replication = false
s3_kms_key_arn        = ""

# IAM — no OIDC in dev (uses EC2-attached role + IAM user)
iam_oidc_provider_arn    = ""
iam_oidc_namespace       = "kubernetes.io"
iam_oidc_service_account = "app-service"

# NOTE: rds_password is intentionally NOT here.
# It is injected via SOPS-encrypted overlay or CI secret.
# See README for the SOPS pattern.
```

