## `environments/prod/main.tf`

```hcl
module "app_infra" {
  source = "../../modules/app-infra"

  project_name           = var.project_name
  environment            = var.environment
  region                 = var.region

  # S3
  s3_enable_replication  = var.s3_enable_replication
  s3_replication_region  = var.s3_replication_region
  s3_kms_key_arn         = var.s3_kms_key_arn

  # RDS
  rds_instance_class       = var.rds_instance_class
  rds_multi_az             = var.rds_multi_az
  rds_allocated_storage    = var.rds_allocated_storage
  rds_db_name              = var.rds_db_name
  rds_username             = var.rds_username
  rds_password             = var.rds_password
  rds_backup_retention_days = var.rds_backup_retention_days
  rds_encrypted            = var.rds_encrypted

  # IAM
  iam_oidc_provider_arn    = var.iam_oidc_provider_arn
  iam_oidc_namespace       = var.iam_oidc_namespace
  iam_oidc_service_account = var.iam_oidc_service_account
}

output "s3_bucket" {
  value = module.app_infra.s3_bucket_name
}

output "s3_replica_bucket" {
  value = module.app_infra.s3_replica_bucket_arn
}

output "rds_endpoint" {
  value = module.app_infra.rds_endpoint
}

output "iam_role_arn" {
  value = module.app_infra.iam_role_arn
}

output "db_connection_string" {
  value     = module.app_infra.db_connection_string
