```hcl
variable "project_name" {
  type    = string
  default = "app"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

# S3
variable "s3_enable_replication" {
  type    = bool
  default = true
}

variable "s3_replication_region" {
  type    = string
  default = "us-west-2"
}

variable "s3_kms_key_arn" {
  type    = string
  default = ""
}

# RDS
variable "rds_instance_class" {
  type    = string
